function caret(range) {
  const [major, minor, patch] = range.slice(1).split(".").map(Number);
  const low = `>=${major}.${minor}.${patch}`;
  if (major > 0) return `${low} <${major + 1}.0.0`;
  if (minor > 0) return `${low} <0.${minor + 1}.0`;
  return `${low} <0.0.${patch + 1}`;
}

