function reachable(starts) {
  const seen = new Set();
  const stack = [...starts];
  while (stack.length) {
    const name = stack.pop();
    if (seen.has(name)) continue;
    seen.add(name);
    stack.push(...graph[name].deps);
  }
  return seen;
}

const prod = reachable(graph.root.deps);
