function oneEditApart(a, b) {
  if (Math.abs(a.length - b.length) > 1 || a === b) return false;
  let i = 0;
  let j = 0;
  let edits = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) {
      i++;
      j++;
      continue;
    }
    edits++;
    if (edits > 1) return false;
    if (a.length > b.length) i++;
    else if (b.length > a.length) j++;
    else {
      i++;
      j++;
    }
  }
  return edits + (a.length - i) + (b.length - j) === 1;
}

function looksLike(name, popular) {
  return popular.filter((p) => oneEditApart(name, p));
}

const popular = ["express", "cross-env", "dotenv", "axios"];
console.log(looksLike("expres", popular));
console.log(looksLike("crossenv", popular));
console.log(looksLike("axois", popular));
