function runOrder(scripts, name) {
  if (!(name in scripts)) throw new Error(`Missing script: ${name}`);
  return [`pre${name}`, name, `post${name}`].filter((script) => script in scripts);
}

const scripts = { prebuild: "node clean.js", build: "tsc", postbuild: "node report.js", test: "node --test", pretest: "npm run build" };
console.log(runOrder(scripts, "build"));
console.log(runOrder(scripts, "test"));
try {
  runOrder(scripts, "deploy");
} catch (error) {
  console.log(error.message);
}
